)

type Broker interface {
	http.Handler
	SendMessage(ctx context.Context, event Event)
}

const (
	keepAliveFrequency = 15 * time.Second
	writeTimeOut       = 5 * time.Second
)

var (
	eventId         uint32
	errWriteTimeOut = errors.New("write timeout")
)

type (
	message struct {
		id             uint32
		event          string
		data           string
		username       string
		clientUniqueId string
	}
	messageChan chan message
	clientsChan chan client
	client      struct {
		id             string
		address        string
		username       string
		clientUniqueId string
		userAgent      string
		diode          *diode
	}
)

func (c client) String() string {
	return fmt.Sprintf("%s (%s - %s - %s - %s)", c.id, c.username, c.clientUniqueId, c.address, c.userAgent)
}

type broker struct {
	// Events are pushed to this channel by the main events-gathering routine
	publish messageChan

	// New client connections
	subscribing clientsChan

	// Closed client connections
	unsubscribing clientsChan
}

func NewBroker() Broker {
	// Instantiate a broker
	broker := &broker{
		publish:       make(messageChan, 100),
		subscribing:   make(clientsChan, 1),
		unsubscribing: make(clientsChan, 1),
	}

	// Set it running - listening and broadcasting events
	go broker.listen()

	return broker
}

func (b *broker) SendMessage(ctx context.Context, evt Event) {
	msg := b.prepareMessage(ctx, evt)
	log.Trace("Broker received new event", "event", msg)
	b.publish <- msg
}

func (b *broker) prepareMessage(ctx context.Context, event Event) message {
	clientUniqueId, _ := request.ClientUniqueIdFrom(ctx)
	username, ok := request.UsernameFrom(ctx)
	if !ok {
		if user, found := request.UserFrom(ctx); found {
			username = user.UserName
		}
	}
	return message{
		id:             atomic.AddUint32(&eventId, 1),
		data:           event.Data(event),
		event:          event.Name(event),
		username:       username,
		clientUniqueId: clientUniqueId,
	}
}

// writeEvent Write to the ResponseWriter, Server Sent Events compatible
func writeEvent(w io.Writer, event message, timeout time.Duration) (err error) {
	flusher, _ := w.(http.Flusher)
	complete := make(chan struct{}, 1)
			// A client has detached and we want to
			// stop sending them messages.
			delete(clients, c)
			log.Debug("Removed client from event broker", "numClients", len(clients), "client", c.String())

		case event := <-b.publish:
			// We got a new event from the outside!
			// Request events go to the sender's other sessions; server events go to all clients.
			for c := range clients {
				if !shouldSendTo(c, event) {
					continue
				}
				log.Trace("Putting event on client's queue", "client", c.String(), "event", event)
				c.diode.put(event)
			}

		case ts := <-keepAlive.C:
			// Send a keep alive message every 15 seconds
			b.SendMessage(context.Background(), &KeepAlive{TS: ts.Unix()})
		}
	}
}

func shouldSendTo(c client, event message) bool {
	if event.clientUniqueId == "" {
		return true
	}
	if c.clientUniqueId == event.clientUniqueId {
		return false
	}
	return event.username == "" || c.username == event.username
}
